1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .cell[data-ghost="true"] { box-shadow: inset 0 0 0 2px currentColor; }
22	  .board[data-paused="true"] { opacity: 0.45; }
23	  .paused { color: #f5c400; font-weight: 600; }
24	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
25	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
26	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
27	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
28	  .next-list { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
29	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; }
30	  .preview .mini { width: 20px; height: 20px; background: transparent; }
31	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
32	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
33	  .help { font-size: 13px; color: #9097a6; }
34	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
35	  button {
36	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
37	    font: inherit; font-weight: 600; cursor: pointer;
38	  }
39	</style>
40	</head>
41	<body>
42	<div class="game">
43	  <div class="board" data-testid="board"></div>
44	  <div class="panel">
45	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
46	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
47	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
48	    <div class="stat"><div class="label">Hold</div><div class="preview" data-testid="hold-piece" data-piece=""></div></div>
49	    <div class="stat"><div class="label">Next</div><div class="next-list" data-testid="next-piece"></div></div>
50	    <div class="status" data-testid="status"><span data-testid="game-over" hidden></span></div>
51	    <div class="paused" data-testid="paused-indicator" hidden>Paused</div>
52	    <button type="button" data-testid="pause-btn" id="pause">Pause</button>
53	    <button type="button" id="new-game">New game</button>
54	    <div class="help">
55	      <kbd>←</kbd> <kbd>→</kbd> move<br>
56	      <kbd>↑</kbd> rotate<br>
57	      <kbd>↓</kbd> soft drop<br>
58	      <kbd>Space</kbd> hard drop<br>
59	      <kbd>C</kbd> <kbd>Shift</kbd> hold<br>
60	      <kbd>P</kbd> <kbd>Esc</kbd> pause
61	    </div>
62	  </div>
63	</div>
64	<script>
65	(function () {
66	  'use strict';
67	
68	  var ROWS = 20, COLS = 10;
69	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
70	  var COLORS = {
71	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
72	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
73	  };
74	  // Spawn orientation, as [row, col] offsets from the piece origin.
75	  var SHAPES = {
76	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
77	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
78	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
79	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
80	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
81	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
82	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
83	  };
84	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
85	  // Level rule (a project decision): the level starts at 1 and rises by one for every
86	  // LINES_PER_LEVEL lines cleared; it never goes down. Gravity runs every dropInterval() ms.
87	  var LINES_PER_LEVEL = 10;
88	  function dropInterval() { return Math.max(100, 1000 - (level - 1) * 100); }
89	  // Preview rule (a project decision): the panel shows only the next piece, in its colour.
90	  var PREVIEW_COUNT = 1;
91	
92	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
93	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
94	  var ROTATIONS = {};
95	  TYPES.forEach(function (t) {
96	    var n = t === 'O' ? 2 : 3;
97	    var states = [SHAPES[t]];
98	    for (var k = 1; k < 4; k++) {
99	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
100	    }
101	    ROTATIONS[t] = states;
102	  });
103	  ROTATIONS.I = [
104	    SHAPES.I,
105	    [[0, 2], [1, 2], [2, 2], [3, 2]],
106	    [[1, 0], [1, 1], [1, 2], [1, 3]],
107	    [[0, 1], [1, 1], [2, 1], [3, 1]]
108	  ];
109	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
110	  var KICKS = [0, -1, 1, -2, 2];
111	
112	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
113	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
114	  // right move during the delay restarts it, and so does a soft drop on a piece that is already
115	  // resting; these share one cap of MAX_RESTARTS per piece. A soft drop that cannot move the piece
116	  // never counts a tick. Hard drop locks at once.
117	  var LOCK_TICKS = 2;
118	  var MAX_RESTARTS = 3;
119	
120	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
121	  // current level. Clearing rows together must always beat clearing the same rows in smaller
122	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
123	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
124	  var LINE_POINTS = [0, 100, 300, 500, 800];
125	  var SOFT_DROP_POINTS = 1;
126	  var HARD_DROP_POINTS = 2;
127	
128	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
129	  // `hold` is the held letter or null; `canHold` is false from a hold until the next lock.
130	  var board, current, queue, bag, score, level, lines, status, hold, canHold, timer = null;
131	  // Pause rule: pausing freezes the lock delay as it stands (ticks and restarts are kept) and
132	  // freezes the gravity clock too. Resuming waits only the part of the interval that was left,
133	  // so toggling pause can never hold back the next gravity step or the lock.
134	  var lastStepAt = 0, pausedLeft = 0;
135	
136	  // ---- DOM ----
137	  var boardEl = document.querySelector('[data-testid="board"]');
138	  var scoreEl = document.querySelector('[data-testid="score"]');
139	  var levelEl = document.querySelector('[data-testid="level"]');
140	  var linesEl = document.querySelector('[data-testid="lines"]');
141	  var nextEl = document.querySelector('[data-testid="next-piece"]');
142	  var gameOverEl = document.querySelector('[data-testid="game-over"]');
143	  var holdEl = document.querySelector('[data-testid="hold-piece"]');
144	  var pausedEl = document.querySelector('[data-testid="paused-indicator"]');
145	  var pauseBtn = document.querySelector('[data-testid="pause-btn"]');
146	  var cellEls = [];
147	  var itemEls = [];
148	  var miniEls = [];
149	
150	  // Fill a 4x2 grid element with mini cells; returns them as [row][col].
151	  function buildMini(grid) {
152	    var rows = [];
153	    for (var mr = 0; mr < 2; mr++) {
154	      rows.push([]);
155	      for (var mc = 0; mc < 4; mc++) {
156	        var m = document.createElement('div');
157	        m.className = 'mini';
158	        grid.appendChild(m);
159	        rows[mr].push(m);
160	      }
161	    }
162	    return rows;
163	  }
164	  var holdMinis = buildMini(holdEl);
165	
166	  for (var r = 0; r < ROWS; r++) {
167	    cellEls.push([]);
168	    for (var c = 0; c < COLS; c++) {
169	      var el = document.createElement('div');
170	      el.className = 'cell';
171	      el.setAttribute('data-testid', 'cell');
172	      el.setAttribute('data-row', String(r));
173	      el.setAttribute('data-col', String(c));
174	      boardEl.appendChild(el);
175	      cellEls[r].push(el);
176	    }
177	  }
178	  // One 4x2 mini grid per upcoming piece. The first grid keeps the older data-testid="next".
179	  for (var i = 0; i < PREVIEW_COUNT; i++) {
180	    var item = document.createElement('div');
181	    item.className = 'preview';
182	    item.setAttribute('data-testid', 'next-piece-item');
183	    nextEl.appendChild(item);
184	    itemEls.push(item);
185	    var grid = item;
186	    if (i === 0) {
187	      grid = document.createElement('div');
188	      grid.className = 'preview';
189	      grid.setAttribute('data-testid', 'next');
190	      item.className = '';
191	      item.appendChild(grid);
192	    }
193	    miniEls.push(buildMini(grid));
194	  }
195	
196	  function paint(el, type) {
197	    el.setAttribute('data-filled', type ? 'true' : 'false');
198	    el.setAttribute('data-piece', type || '');
199	    el.style.backgroundColor = type ? COLORS[type] : '';
200	  }
201	
202	  function paintMini(minis, type) {
203	    for (var mr = 0; mr < 2; mr++) {
204	      for (var mc = 0; mc < 4; mc++) paint(minis[mr][mc], '');
205	    }
206	    if (type) SHAPES[type].forEach(function (p) { paint(minis[p[0]][p[1]], type); });
207	  }
208	
209	  function render() {
210	    var view = board.map(function (row) { return row.slice(); });
211	    if (current) {
212	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
213	    }
214	    var ghostView = {};
215	    ghostCells().forEach(function (p) { ghostView[p[0] + ',' + p[1]] = true; });
216	    for (var r = 0; r < ROWS; r++) {
217	      for (var c = 0; c < COLS; c++) {
218	        var cell = cellEls[r][c];
219	        paint(cell, view[r][c]);
220	        // A ghost cell under the falling piece is shown as the piece, not as ghost.
221	        var ghost = !view[r][c] && ghostView[r + ',' + c] === true;
222	        cell.setAttribute('data-ghost', ghost ? 'true' : 'false');
223	        cell.style.color = ghost ? COLORS[current.type] : '';
224	      }
225	    }
226	    var paused = status === 'paused';
227	    boardEl.setAttribute('data-paused', paused ? 'true' : 'false');
228	    pausedEl.hidden = !paused;
229	    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
230	
231	    for (var i = 0; i < PREVIEW_COUNT; i++) {
232	      var upcoming = queue[i] || '';
233	      itemEls[i].setAttribute('data-piece', upcoming);
234	      paintMini(miniEls[i], upcoming);
235	    }
236	    holdEl.setAttribute('data-piece', hold || '');
237	    paintMini(holdMinis, hold);
238	
239	    scoreEl.textContent = String(score);
240	    levelEl.textContent = String(level);
241	    linesEl.textContent = String(lines);
242	    var over = status === 'gameover';
243	    gameOverEl.hidden = !over;
244	    gameOverEl.textContent = over ? 'Game over' : '';
245	  }
246	
247	  // ---- Pieces ----
248	  function randomPiece() {
249	    if (!bag.length) {
250	      bag = TYPES.slice();
251	      for (var i = bag.length - 1; i > 0; i--) {
252	        var j = Math.floor(Math.random() * (i + 1));
253	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
254	      }
255	    }
256	    return bag.pop();
257	  }
258	
259	  // Keep at least PREVIEW_COUNT pieces waiting, so the preview is always full.
260	  function fillQueue() {
261	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
262	  }
263	
264	  function takeNext() {
265	    fillQueue();
266	    var type = queue.shift();
267	    fillQueue();
268	    return type;
269	  }
270	
271	  function pieceCells(piece) {
272	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
273	  }
274	
275	  function fits(cells) {
276	    return cells.every(function (p) {
277	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
278	    });
279	  }
280	
281	  // Bring in a piece of the given type (default: the next in the queue) at the spawn position.
282	  function spawn(type) {
283	    type = type || takeNext();
284	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
285	    if (!fits(pieceCells(piece))) {
286	      current = null;
287	      status = 'gameover';
288	      stopTimer();
289	      return;
290	    }
291	    current = piece;
292	  }
293	
294	  // Where the falling piece would land if dropped straight down. Empty when there is no piece.
295	  function ghostCells() {
296	    if (!current) return [];
297	    var ghost = { type: current.type, row: current.row, col: current.col, rot: current.rot };
298	    while (fits(pieceCells({ type: ghost.type, row: ghost.row + 1, col: ghost.col, rot: ghost.rot }))) ghost.row++;
299	    return pieceCells(ghost);
300	  }
301	
302	  function move(dr, dc) {
303	    if (!current) return false;
304	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
305	    if (!fits(pieceCells(moved))) return false;
306	    current.row = moved.row;
307	    current.col = moved.col;
308	    return true;
309	  }
310	
311	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
312	  function shift(dc) {
313	    if (move(0, dc)) restartLock();
314	  }
315	
316	  // Down, one row. On a piece already resting it counts no lock tick and restarts the delay like a
317	  // sideways move, sharing the same cap.
318	  function softDrop() {
319	    if (move(1, 0)) {
320	      current.lockTicks = 0;
321	      score += SOFT_DROP_POINTS;
322	    } else {
323	      restartLock();
324	    }
325	  }
326	
327	  function restartLock() {
328	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
329	      current.lockTicks = 0;
330	      current.restarts++;
331	    }
332	  }
333	
334	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
335	  function rotateCW() {
336	    if (!current) return false;
337	    var rot = (current.rot + 1) % 4;
338	    for (var i = 0; i < KICKS.length; i++) {
339	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
340	      if (fits(pieceCells(turned))) {
341	        current.col = turned.col;
342	        current.rot = rot;
343	        return true;
344	      }
345	    }
346	    return false;
347	  }
348	
349	  // Remove every full row; the rows above drop down. Returns how many rows went.
350	  function clearLines() {
351	    var kept = board.filter(function (row) { return !row.every(Boolean); });
352	    var cleared = ROWS - kept.length;
353	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
354	    board = kept;
355	    return cleared;
356	  }
357	
358	  function lock() {
359	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
360	    current = null;
361	    var cleared = clearLines();
362	    var before = Math.floor(lines / LINES_PER_LEVEL);
363	    lines += cleared;
364	    score += LINE_POINTS[cleared] * level;
365	    var gained = Math.floor(lines / LINES_PER_LEVEL) - before;
366	    if (gained > 0) {
367	      level += gained;
368	      startTimer();
369	    }
370	    canHold = true;
371	    spawn();
372	  }
373	
374	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
375	  function gravityStep() {
376	    if (status !== 'running' || !current) return false;
377	    if (move(1, 0)) {
378	      current.lockTicks = 0;
379	      return true;
380	    }
381	    current.lockTicks++;
382	    if (current.lockTicks >= LOCK_TICKS) lock();
383	    return false;
384	  }
385	
386	  function gravity() {
387	    gravityStep();
388	    render();
389	  }
390	
391	  function onTimer() {
392	    lastStepAt = Date.now();
393	    gravity();
394	  }
395	
396	  function stopTimer() {
397	    if (timer !== null) { clearInterval(timer); clearTimeout(timer); timer = null; }
398	  }
399	
400	  function startTimer() {
401	    stopTimer();
402	    lastStepAt = Date.now();
403	    timer = setInterval(onTimer, dropInterval());
404	  }
405	
406	  // Toggle pause. Nothing happens once the game is over.
407	  function togglePause() {
408	    if (status === 'running') {
409	      pausedLeft = Math.max(0, dropInterval() - (Date.now() - lastStepAt));
410	      stopTimer();
411	      status = 'paused';
412	    } else if (status === 'paused') {
413	      status = 'running';
414	      timer = setTimeout(function () {
415	        timer = null;
416	        onTimer();
417	        if (status === 'running' && timer === null) startTimer();
418	      }, Math.min(pausedLeft, dropInterval()));
419	    }
420	    render();
421	  }
422	
423	  // Put the falling piece aside: bring in the held piece, or the next one if nothing is held.
424	  // Refused after a hold until a piece locks.
425	  function holdPiece() {
426	    if (!canHold) return;
427	    var from = hold;
428	    hold = current.type;
429	    canHold = false;
430	    current = null;
431	    spawn(from);
432	  }
433	
434	  // ---- Actions ----
435	  function input(action) {
436	    if (action === 'pause') return togglePause();
437	    if (status !== 'running' || !current) return;
438	    if (action === 'left') shift(-1);
439	    else if (action === 'right') shift(1);
440	    else if (action === 'rotateCW') rotateCW();
441	    else if (action === 'softDrop') softDrop();
442	    else if (action === 'hold') holdPiece();
443	    else if (action === 'hardDrop') {
444	      while (move(1, 0)) score += HARD_DROP_POINTS;
445	      lock();
446	    }
447	    render();
448	  }
449	
450	  function toQueue(list) {
451	    return (Array.isArray(list) ? list : [])
452	      .map(function (t) { return String(t).toUpperCase(); })
453	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
454	  }
455	
456	  function newGame(list) {
457	    board = [];
458	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
459	    bag = [];
460	    queue = toQueue(list);
461	    score = 0;
462	    level = 1;
463	    lines = 0;
464	    hold = null;
465	    canHold = true;
466	    status = 'running';
467	    current = null;
468	    spawn();
469	    if (status === 'running') startTimer();
470	    render();
471	  }
472	
473	  function setQueue(list) {
474	    queue = toQueue(list);
475	    fillQueue();
476	    render();
477	  }
478	
479	  function setBoard(rows) {
480	    for (var r = 0; r < ROWS; r++) {
481	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
482	      for (var c = 0; c < COLS; c++) {
483	        var ch = line.charAt(c).toUpperCase();
484	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
485	      }
486	    }
487	    render();
488	  }
489	
490	  function getBoard() {
491	    return board.map(function (row) {
492	      return row.map(function (t) { return t || '.'; }).join('');
493	    });
494	  }
495	
496	  function getState() {
497	    return {
498	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
499	      next: queue.slice(),
500	      score: score,
501	      level: level,
502	      lines: lines,
503	      status: status,
504	      dropInterval: dropInterval(),
505	      hold: hold,
506	      ghost: ghostCells()
507	    };
508	  }
509	
510	  function tick(n) {
511	    var steps = n === undefined ? 1 : n;
512	    for (var i = 0; i < steps; i++) gravity();
513	  }
514	
515	  // For testing: set the level. The gravity timer picks up the new interval.
516	  function setLevel(n) {
517	    level = Math.max(1, Math.floor(Number(n)) || 1);
518	    if (status === 'running') startTimer();
519	    render();
520	  }
521	
522	  window.__tetris = {
523	    setLevel: setLevel,
524	    newGame: newGame,
525	    setQueue: setQueue,
526	    setBoard: setBoard,
527	    tick: tick,
528	    input: input,
529	    getBoard: getBoard,
530	    getState: getState
